.student-english-course{max-width:1100px;margin:auto;padding:24px;color:#24352e;font-family:system-ui,-apple-system,"Microsoft YaHei",sans-serif;--van-primary-color:#22634b;--van-button-primary-background:#22634b;--van-button-primary-border-color:#22634b;--van-tabs-bottom-bar-color:#22634b;--van-radio-checked-icon-color:#22634b}.student-english-course h1{font-size:clamp(28px,4vw,42px);line-height:1.25;margin:12px 0}.student-english-course h2{font-size:22px;line-height:1.4}.student-english-course p,.student-english-course li{line-height:1.8}.student-english-header{display:grid;grid-template-columns:minmax(0,1fr) minmax(200px,300px);gap:24px;margin-bottom:24px}.student-english-muted{color:#64746b}.student-english-links,.student-english-actions{display:flex;flex-wrap:wrap;align-items:center;gap:12px;margin:18px 0}.student-english-course a{color:#22634b;min-height:44px;display:inline-flex;align-items:center}.student-english-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(min(100%,260px),1fr));gap:14px;margin-top:20px}.student-english-card{border-radius:12px;overflow:hidden}.student-english-panel{padding:24px;background:#fff;border:1px solid #e2e8e1;border-radius:14px;margin-top:20px;overflow-wrap:anywhere}.student-english-panel blockquote{margin:18px 0;padding:20px;background:#f2f6f2;line-height:1.8}.student-english-notice{background:#edf3ee;padding:14px 18px;border-radius:10px}.student-english-gap{color:#9f3131}.student-english-message{border-bottom:1px solid #e2e8e1;padding:12px 0;white-space:pre-wrap}.student-english-course :deep(.van-button){min-height:44px}.student-english-course :deep(.van-cell){min-height:44px;line-height:1.6}.student-english-course :deep(.van-field__label){width:90px;white-space:normal}.student-english-course :deep(.van-radio){min-height:44px;padding:8px 0}.student-english-course :deep(.van-field__control){background:transparent;border:0;padding:0;min-height:0;font:inherit;box-shadow:none}.student-english-course :deep(.van-cell__